# Copia real de usuarios antes de cada cambio (contraseñas, altas y bajas). Uso: python3 fix13.py
import os,subprocess,sys,base64,shutil
API='/var/www/vibkaptur/public/api'; PRIV='/var/www/vibkaptur/private'
F={'miclave.php':'','usuarios.php':''}
for n,c in F.items():
    open('/tmp/_'+n,'wb').write(base64.b64decode(c))
    if subprocess.run(['php','-l','/tmp/_'+n],capture_output=True).returncode!=0: print('FALLO de sintaxis en',n,'. NO SE HA TOCADO NADA'); sys.exit(1)
os.makedirs('/root/vibk_api_antes',exist_ok=True)
ra=os.stat(os.path.join(API,'clave.php'))
for n in F:
    p=os.path.join(API,n); shutil.copy2(p,'/root/vibk_api_antes/'+n+'.antes_fix13'); shutil.copyfile('/tmp/_'+n,p); os.chown(p,ra.st_uid,ra.st_gid); os.chmod(p,ra.st_mode&0o7777)
bd=os.path.join(PRIV,'backups'); ru=os.stat(os.path.join(PRIV,'users.php'))
os.makedirs(bd,exist_ok=True); os.chown(bd,ru.st_uid,ru.st_gid)
print('COPIAS DE USUARIOS ACTIVADAS')
